215→    private fun isSlayerBoss(entity: Entity): Boolean {
216→        val living = entity as? net.minecraft.world.entity.LivingEntity ?: return false
217→        val custom = living.customName?.string?.let { cleanText(it) } ?: ""
218→        if (custom.isNotEmpty() && matchesSlayerBossName(custom)) return true
219→
220→        val displays = MobHeadDisplayDetector.getHeadDisplays(living)
221→        for (comp in displays.textDisplays) {
222→            val text = cleanText(comp.string)
223→            if (text.isNotEmpty() && matchesSlayerBossName(text)) return true
224→        }
225→        return false
226→    }
227→
228→    private fun matchesSlayerBossName(cleanLower: String): Boolean {
229→        val s = cleanLower.lowercase()
230→        return s.contains("revenant horror") ||
231→            s.contains("мститель") ||
232→            s.contains("tarantula broodfather") ||
233→            s.contains("тарантул") ||
234→            s.contains("sven packmaster") ||
235→            s.contains("свен")
236→    }
237→
238→    private fun cleanText(text: String): String {
239→        return text.replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "").trim()
240→    }
