242→    private fun renderEntityBox(context: RenderContext, entity: Entity, color: Int, globalAlpha: Float, outline: Boolean = false) {
243→        val r = ((color shr 16) and 0xFF) / 255f
244→        val g = ((color shr 8) and 0xFF) / 255f
245→        val b = (color and 0xFF) / 255f
246→        val baseAlpha = ((color shr 24) and 0xFF) / 255f
247→        
248→        // Применяем глобальную прозрачность
249→        val a = baseAlpha * globalAlpha
250→        
251→        context.renderBox(entity.boundingBox, r, g, b, a, !outline)
252→    }
253→
254→    private fun isStarredDungeonMob(entity: net.minecraft.world.entity.LivingEntity, nowMs: Long): Boolean {
255→        val id = entity.id
256→        val cached = starredDungeonCache[id]
257→        if (cached != null && nowMs - cached.first <= 50L) {
258→            return cached.second
259→        }
260→
261→        val displays = MobHeadDisplayDetector.getHeadDisplays(entity)
262→        var starred = false
263→        for (comp in displays.textDisplays) {
264→            if (comp.string.contains("✯")) {
265→                starred = true
266→                break
267→            }
268→        }
269→        starredDungeonCache[id] = nowMs to starred
270→        return starred
271→    }
