273→    private fun applyGlow(entity: Entity, color: Int) {
274→        val id = entity.id
275→        managedGlowIds.add(id)
276→        seenGlowIds.add(id)
277→        glowColorsByEntityId[id] = color
278→        if (!entity.isCurrentlyGlowing) {
279→            entity.setGlowingTag(true)
280→        }
281→    }
