283→    private fun cleanupGlow(level: net.minecraft.client.multiplayer.ClientLevel) {
284→        if (managedGlowIds.isEmpty()) return
285→        val iter = managedGlowIds.iterator()
286→        while (iter.hasNext()) {
287→            val id = iter.next()
288→            if (seenGlowIds.contains(id)) continue
289→            val entity = level.getEntity(id)
290→            if (entity != null) {
291→                entity.setGlowingTag(false)
292→            }
293→            glowColorsByEntityId.remove(id)
294→            iter.remove()
295→        }
296→    }
297→
298→    private fun clearAllGlow(level: net.minecraft.client.multiplayer.ClientLevel) {
299→        if (managedGlowIds.isEmpty()) return
300→        for (id in managedGlowIds) {
301→            val entity = level.getEntity(id)
302→            if (entity != null) {
303→                entity.setGlowingTag(false)
304→            }
305→        }
306→        managedGlowIds.clear()
307→        glowColorsByEntityId.clear()
308→        seenGlowIds.clear()
309→    }
